// Expects body: { script: "...", voice_id: "...", approved: true }
// Telegram approval: user replies 'approve' to the script message,
// which triggers this webhook from the chatbot workflow.
const body = $json.body || $json;

if (!body.approved) {
  throw new Error('Not approved — workflow halted.');
}

const script = body.script || body.scriptText;
if (!script) throw new Error('No script provided in body.');

// Extract just the spoken parts (hook + story + peak) for TTS
// Strip markdown headers from the script
const spokenText = script
  .replace(/TITLE:.*\n/g, '')
  .replace(/HOOK \(0-5s\):\n/g, '')
  .replace(/STORY \(45-60s\):\n/g, '')
  .replace(/PEAK ANSWER:\n/g, ' ...')
  .replace(/PINNED COMMENT:\n.*$/s, '')
  .replace(/---.*$/s, '')
  .trim();

return [{ json: {
  script,
  spokenText,
  voiceId: body.voice_id || $env.ELEVENLABS_VOICE_ID || 'pNInz6obpgDQGcFmaJgB',
  title: body.title || 'Soccer Short'
}}];

// At this point $binary.data contains the MP3 voiceover.
// Next step: send to video generation API (RunwayML / HeyGen / Kling).
// This node prepares the HeyGen talking-head request.
// Swap for RunwayML/Kling if you want cinematic clips instead of talking head.

const upstream = $('Validate & Extract Script').first().json;

// HeyGen avatar video request
const heygenPayload = {
  video_inputs: [{
    character: {
      type: 'avatar',
      avatar_id: $env.HEYGEN_AVATAR_ID || 'josh_lite3_20230714',
      avatar_style: 'normal'
    },
    voice: {
      type: 'audio',
      // We'll use the ElevenLabs audio we just generated
      // HeyGen supports uploading audio for lip sync
      audio_url: 'POPULATED_IN_NEXT_STEP'
    },
    background: {
      type: 'color',
      value: '#000000'
    }
  }],
  dimension: { width: 1080, height: 1920 },
  caption: false
};

return [{ json: { ...upstream, heygenPayload, note: 'Upload ElevenLabs audio to HeyGen then poll for video completion.' } }];

// HeyGen returns a video_id immediately; video renders async (1-5 min).
// Poll /v1/video.status until status=completed, then get download_url.
const heygenRes = $input.first().json;
const upstream = $('Validate & Extract Script').first().json;

return [{ json: {
  videoId: heygenRes.data?.video_id,
  title: upstream.title,
  script: upstream.script,
  status: 'rendering',
  note: 'Poll GET https://api.heygen.com/v1/video.status.get?video_id={videoId} until status=completed'
}}];
